//! Replays the corpora in `tests/fixtures/`, all generated by running the original Go
//! implementation over the same inputs:
//!
//! * `ip_string.tsv` - `net.IP.String()` over valid, mapped, compressed and malformed bodies;
//! * `answers.tsv` - `isUpstreamBlockedMsg` + `resolvedAddressesMsg` over synthetic answer sets;
//! * `blocks_trace.tsv` - the dynamic block tracker over a scripted clock.

use std::path::PathBuf;

use diting_dns_core::block::{BlockConfig, DynamicBlocks};
use diting_dns_core::payload::{decode_answer_request, LAYOUT_VERSION};
use diting_dns_core::{inspect, AnswerEntry};
use diting_go_compat::ip::go_ip_string;

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn read(name: &str) -> String {
    let path = fixtures().join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("{} is committed: {error}", path.display()))
}

fn decode_hex(text: &str) -> Vec<u8> {
    assert_eq!(text.len() % 2, 0, "hex length {text:?}");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("hex pair"))
        .collect()
}

#[test]
fn ip_string_matches_go() {
    let text = read("ip_string.tsv");
    let mut rows = 0;
    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let (encoded, expected) = line.split_once('\t').expect("two columns");
        let bytes = if encoded == "-" {
            Vec::new()
        } else {
            decode_hex(encoded)
        };
        assert_eq!(
            go_ip_string(&bytes),
            expected,
            "row {line_number}: {}",
            encoded
        );
        rows += 1;
    }
    assert_eq!(rows, 102, "one row per scripted address");
}

#[test]
fn answer_inspection_matches_go() {
    let text = read("answers.tsv");
    let mut rows = 0;
    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 3, "row {line_number} has the wrong width");
        let (spec, blocked, addresses) = (fields[0], fields[1] == "1", fields[2]);

        // Only A/AAAA records reach the kernel: Go's encoder skips every other type, and so does
        // the fixture reader below.
        let mut bodies: Vec<(u8, Vec<u8>)> = Vec::new();
        if spec != "none" {
            for record in spec.split('|') {
                // `cname` / `txt` carry no address, so they never reach the kernel either.
                let Some((kind, body)) = record.split_once(':') else {
                    continue;
                };
                let rrtype = match kind {
                    "A" => 1u8,
                    "AAAA" => 28u8,
                    _ => continue,
                };
                bodies.push((
                    rrtype,
                    if body.is_empty() {
                        Vec::new()
                    } else {
                        decode_hex(body)
                    },
                ));
            }
        }
        let entries: Vec<AnswerEntry<'_>> = bodies
            .iter()
            .map(|(rrtype, address)| AnswerEntry {
                rrtype: *rrtype,
                address,
            })
            .collect();
        let inspection = inspect(&entries);
        assert_eq!(inspection.blocked, blocked, "row {line_number}: {spec}");
        assert_eq!(inspection.addresses, addresses, "row {line_number}: {spec}");
        rows += 1;
    }
    assert_eq!(rows, 25, "one row per scripted answer");
}

#[test]
fn dynamic_blocks_trace_matches_go() {
    let text = read("blocks_trace.tsv");
    let blocks = DynamicBlocks::new();
    let mut rows = 0;
    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 10, "row {line_number} has the wrong width");
        let op = fields[1];
        let domain = fields[2];
        let enabled = fields[3] == "1";
        let threshold: u32 = fields[4].parse().expect("threshold");
        let window_seconds: i64 = fields[5].parse().expect("window");
        let nxdomain_seconds: i64 = fields[6].parse().expect("nxdomain window");
        let fallback: u32 = fields[7].parse().expect("fallback");
        let now_ns: i64 = fields[8].parse().expect("now");
        let expected = fields[9];

        if op == "reset" {
            blocks.reset();
            assert_eq!(blocks.len(), 0);
            assert_eq!(expected, "-");
        } else {
            assert_eq!(op, "response", "row {line_number}: unknown op {op}");
            let response = blocks.response_for(
                domain,
                &BlockConfig {
                    enabled,
                    request_threshold: threshold,
                    window_ns: window_seconds * 1_000_000_000,
                    nx_domain_ns: nxdomain_seconds * 1_000_000_000,
                },
                fallback,
                now_ns,
            );
            assert_eq!(
                response.to_string(),
                expected,
                "row {line_number}: {domain}"
            );
        }
        rows += 1;
    }
    assert_eq!(rows, 25, "one row per scripted call");
}

/// The encoded request the Go side builds (it is what the kernel actually receives) decodes back
/// into the same entries, so the layouts cannot drift apart silently.
#[test]
fn payload_layout_round_trips_the_fixture_records() {
    let mut payload = vec![LAYOUT_VERSION];
    payload.extend_from_slice(&2u32.to_le_bytes());
    payload.extend_from_slice(&1u8.to_le_bytes());
    payload.extend_from_slice(&4u16.to_le_bytes());
    payload.extend_from_slice(&[0, 0, 0, 0]);
    payload.extend_from_slice(&28u8.to_le_bytes());
    payload.extend_from_slice(&16u16.to_le_bytes());
    payload.extend_from_slice(&[0u8; 16]);

    let entries = decode_answer_request(&payload).expect("well formed");
    assert_eq!(entries.len(), 2);
    assert_eq!(entries[0].rrtype, 1);
    assert_eq!(entries[0].address, &[0, 0, 0, 0]);
    assert_eq!(entries[1].rrtype, 28);
    assert_eq!(entries[1].address, &[0u8; 16]);
}
